// Command fixturelabels writes labels_gen.go: one fixture.Label variable per
// label the rows in fixtures/ define (ADR-0001 style: the YAML is the source,
// the Go file is generated and never hand-edited).
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/format"
	"log"
	"os"
	"strings"
	"unicode"

	"hexletbasics/internal/fixture"
)

// labelsFileMode is the permission of the generated file: owner-only is what
// gosec asks of a file a tool writes; git does not keep the mode.
const labelsFileMode = 0o600

func main() {
	dir := flag.String("dir", "fixtures", "directory of the fixture YAML files")
	out := flag.String("out", "labels_gen.go", "file to write")

	flag.Parse()

	names, err := fixture.LabelNames(*dir)
	if err != nil {
		log.Fatal(err)
	}

	src, err := render(names)
	if err != nil {
		log.Fatal(err)
	}

	err = os.WriteFile(*out, src, labelsFileMode)
	if err != nil {
		log.Fatal(err)
	}
}

// render is the gofmt-ed source of labels_gen.go for the labels, which are
// already in name order. Two labels that spell the same identifier fail here
// instead of as a redeclaration in the generated file.
func render(names []string) ([]byte, error) {
	var buf bytes.Buffer
	buf.WriteString("// Code generated by cmd/fixturelabels; DO NOT EDIT.\n\npackage fixture\n\nvar (\n")

	taken := map[string]string{}

	for _, name := range names {
		ident := identifier(name)
		if ident == "" {
			return nil, errs.With("label", name).Errorf("fixture label has no letters or digits to name a variable after")
		}

		if other, dup := taken[ident]; dup {
			return nil, errs.With("label", name, "other_label", other, "identifier", ident).Errorf("two fixture labels become the same variable; rename one")
		}

		taken[ident] = name
		fmt.Fprintf(&buf, "\t%s = LabelOf(%q)\n", ident, name)
	}

	buf.WriteString(")\n")

	src, err := format.Source(buf.Bytes())
	if err != nil {
		return nil, errs.Wrapf(err, "format generated source")
	}

	return src, nil
}

// identifier is a label in the exported-name form: user_removed → UserRemoved.
func identifier(label string) string {
	var builder strings.Builder

	for part := range strings.SplitSeq(label, "_") {
		if part == "" {
			continue
		}

		runes := []rune(part)
		runes[0] = unicode.ToUpper(runes[0])
		builder.WriteString(string(runes))
	}

	return builder.String()
}
